#include <string.h>
#include <stdint.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head; /* next write position */
    size_t tail; /* next read position  */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;
    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    memset(rb, 0, sizeof(*rb));
    free(rb /* NULL-safe via our own rb_destroy */);
    (void)0; /* suppress – the above is fine in practice */
}

__attribute__((cleanup(free_cleanup))) uint8_t *rb_destroy_buf(uint8_t *p) { free(p); }

static void free_cleanup(uint8_t **ptr) { if (*ptr) free(*ptr); }

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;   /* next write position */
    size_t tail;   /* next read position  */
    size_t count;  /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;
    ringbuf_t *rb = (ringbuf_t *)malloc(sizeof(*rb));
    if (!rb)
        return NULL;
    rb->buf = (uint8_t *)calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static size_t min_size(size_t a, size_t b) { return a < b ? a : b; }

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data)
        return 0;
    if (len == 0 || rb->count == rb->capacity)
        return 0;

    size_t avail = rb->capacity - rb->count;
    size_t to_write = min_size(len, avail);

    /* Case A: the write fits in a single contiguous span */
    if (rb->head + to_write <= rb->capacity) {
        memcpy(rb->buf + rb->head, data, to_write);
    } else {
        /* Case B: must wrap around */
        size_t first_part = rb->capacity - rb->head; /* bytes until end of buffer */
        memcpy(rb->buf + rb->head, data, first_part);
        memcpy(rb->buf, data + first_part, to_write - first_part);
    }

    rb->head = (rb->head + to_write) % rb->capacity;
    rb->count += to_write;
    return to_write;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->count == 0)
        return 0;

    size_t to_read = min_size(len, rb->count);

    if (rb->tail + to_read <= rb->capacity) {
        memcpy(out, rb->buf + rb->tail, to_read);
    } else {
        size_t first_part = rb->capacity - rb->tail;
        memcpy(out, rb->buf + rb->tail, first_part);
        memcpy(out + first_part, rb->buf, to_read - first_part);
    }

    rb->tail = (rb->tail + to_read) % rb->capacity;
    rb->count -= to_read;
    return to_read;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->count == 0)
        return 0;

    size_t to_copy = min_size(len, rb->count);

    if (rb->tail + to_copy <= rb->capacity) {
        memcpy(out, rb->buf + rb->tail, to_copy);
    } else {
        size_t first_part = rb->capacity - rb->tail;
        memcpy(out, rb->buf + rb->tail, first_part);
        memcpy(out + first_part, rb->buf, to_copy - first_part);
    }

    return to_copy;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    /* Test 1: create/destroy */
    ringbuf_t *rb = rb_create(8);
    if (!rb) { printf("FAIL: rb_create\n"); return 1; }
    if (rb_capacity(rb) != 8) { printf("FAIL: capacity\n"); return 1; }
    if (rb_size(rb) != 0) { printf("FAIL: initial size\n"); return 1; }

    /* Test 2: write + read */
    uint8_t msg[] = {0,1,2,3,4,5,6,7};
    size_t w = rb_write(rb, msg, sizeof(msg));
    if (w != 8) { printf("FAIL: write %zu expected 8\n", w); return 1; }
    if (rb_size(rb) != 8) { printf("FAIL: size after write\n"); return 1; }

    uint8_t buf[8];
    size_t r = rb_read(rb, buf, sizeof(buf));
    if (r != 8) { printf("FAIL: read %zu\n", r); return 1; }
    if (rb_size(rb) != 0) { printf("FAIL: size after read\n"); return 1; }
    if (memcmp(buf, msg, 8) != 0) { printf("FAIL: data mismatch\n"); return 1; }

    /* Test 3: wrap-around write */
    uint8_t more[] = {10,11,12};
    w = rb_write(rb, more, 3);
    if (w != 3) { printf("FAIL: wrap-write %zu\n", w); return 1; }

    /* consume first 3 */
    uint8_t tmp[3];
    r = rb_read(rb, tmp, 3);
    if (r != 3 || tmp[0]!=0||tmp[1]!=1||tmp[2]!=2) { printf("FAIL: read-after-wrap\n"); return 1; }

    /* now write more to force wrap */
    uint8_t fill[] = {20,21,22,23,24};
    w = rb_write(rb, fill, 5);
    if (w != 5) { printf("FAIL: forcing-wrap-write %zu\n", w); return 1; }

    uint8_t out[8];
    r = rb_read(rb, out, 8);
    if (r != 8 || memcmp(out, more+3, 1) != 0) { printf("FAIL: partial consume test\n"); return 1; }
    /* remaining should be: 20,21,22,23,24 + one byte slot (garbage/zero but logically gone) */

    /* Test 4: partial write when full */
    ringbuf_t *rb2 = rb_create(3);
    uint8_t three[] = {1,2,3};
    w = rb_write(rb2, three, 3);
    if (w != 3) { printf("FAIL: fill\n"); return 1; }
    uint8_t extra[] = {99};
    w = rb_write(rb2, extra, 1);  /* full — should store 0 but spec says "what fits" => already full so 0 */
    if (w != 0) { printf("FAIL: partial-full returned %zu\n", w); return 1; }

    /* Test 5: peek */
    ringbuf_t *rb3 = rb_create(4);
    uint8_t d[] = {10,20};
    rb_write(rb3, d, 2);
    uint8_t peeked[4];
    size_t p = rb_peek(rb3, peeked, sizeof(peeked));
    if (p != 2 || peeked[0]!=10 || peeked[1]!=20) { printf("FAIL: peek\n"); return 1; }
    if (rb_size(rb3) != 2) { printf("FAIL: peek changed size\n"); return 1; }

    /* Test 6: clear */
    rb_clear(rb3);
    if (rb_size(rb3) != 0) { printf("FAIL: clear\n"); return 1; }

    /* Test 7: NULL safety */
    rb_destroy(NULL);
    if (rb_write(NULL, d, 2) != 0) { printf("FAIL: write(NULL)\n"); return 1; }
    if (rb_read(NULL, d, 2) != 0) { printf("FAIL: read(NULL)\n"); return 1; }

    rb_destroy(rb);
    rb_destroy(rb2);
    rb_destroy(rb3);

    /* Test 8: create with capacity=0 */
    if (rb_create(0) != NULL) { printf("FAIL: rb_create(0)\n"); return 1; }

    printf("ALL TESTS PASSED\n");
    return 0;
}

